node --input-type=module <<'JS'
import { readFileSync, writeFileSync, appendFileSync } from 'node:fs';
const lines = readFileSync('/tmp/sgui-proposal/sgui-summary.md', 'utf8').split(/\r?\n/);
const titleIndex = lines.findIndex(line => line.trim());
const title = lines[titleIndex]?.trim();
if (!title) throw new Error('AI output is missing a PR title.');
const summary = lines.slice(titleIndex + 1).join('\n').trim();
const required = ['Task IDs', 'Behavior and owned contracts', 'Examples and tests', 'Validation evidence', 'Unverified limitations'];
for (const heading of required) {
  const section = summary.match(new RegExp(`^## ${heading}\\r?\\n([\\s\\S]*?)(?=^## |$(?![\\s\\S]))`, 'm'));
  if (!section?.[1].trim()) throw new Error(`AI output is missing evidence section: ${heading}`);
}
writeFileSync(`${process.env.RUNNER_TEMP}/sgui-pr-body`, `Generated component proposal; author-reported evidence requires reviewer verification.\n\n${summary}\n`);
writeFileSync(`${process.env.RUNNER_TEMP}/sgui-pr-title`, `${title}\n`);
appendFileSync(process.env.GITHUB_OUTPUT, `title=${title}\n`);
JS

