import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
const base = execFileSync('git', ['rev-parse', 'HEAD'], { encoding: 'utf8' }).trim();
const patch = createHash('sha256').update(readFileSync('/tmp/sgui-proposal/sgui.patch')).digest('hex');
const run = `${process.env.GITHUB_SERVER_URL}/${process.env.GITHUB_REPOSITORY}/actions/runs/${process.env.GITHUB_RUN_ID}`;
appendFileSync(`${process.env.RUNNER_TEMP}/sgui-pr-body`, `\n## Workflow validation receipt\nValidated applied proposal working tree: base HEAD ${base}; ai-proposal sgui.patch SHA-256 ${patch}. This is not a tested future PR commit SHA.\nCommands completed successfully before this receipt: pnpm exec commitlint --edit (generated title file), pnpm check, pnpm build:browser-docs.\nRun/job logs and ai-proposal artifact: ${run} (configured retention: 14 days; continued availability unverified).\nFull browser/packed-consumer matrix, actual AI/token isolation, physical-device and assistive-technology acceptance remain unverified by this workflow. Review the title, evidence and behavior before any separately authorized squash merge.\n`);
